mapper.select:
SELECT target.user_id AS userId,
       s.start_time   AS startTime,
       s.end_time     AS endTime
FROM calendar_members target
JOIN calendar_members theirs ON theirs.user_id = target.user_id AND theirs.status = 'accepted'
JOIN schedules s ON s.calendar_id = theirs.calendar_id
WHERE target.calendar_id = #{calendarId}
  AND target.status = 'accepted'
  AND s.start_time < #{rangeEnd}
  AND s.end_time > #{rangeStart}
